const app = ($json.query && $json.query.app) || 'manual';
const body = $json.body || {};
let name = 'Unknown', filePaths = [], sizeBytes = null;
const eventType = body.eventType || 'Unknown';

if (app === 'sonarr') {
  name = (body.series && body.series.title) || name;
  if (body.episodeFile) {
    filePaths = [body.episodeFile.relativePath];
    sizeBytes = body.episodeFile.size || null;
  } else if (Array.isArray(body.episodeFiles)) {
    filePaths = body.episodeFiles.map(f => f.relativePath);
    sizeBytes = body.episodeFiles.reduce((a, f) => a + (f.size || 0), 0);
  }
} else if (app === 'radarr') {
  name = (body.movie && body.movie.title) || name;
  if (body.movieFile) {
    filePaths = [body.movieFile.relativePath];
    sizeBytes = body.movieFile.size || null;
  }
} else if (app === 'lidarr') {
  name = (body.artist && body.artist.name) || name;
  if (Array.isArray(body.trackFiles)) {
    filePaths = body.trackFiles.map(f => f.relativePath);
    sizeBytes = body.trackFiles.reduce((a, f) => a + (f.size || 0), 0);
  }
} else if (app === 'readarr') {
  name = (body.author && body.author.authorName) || (body.book && body.book.title) || name;
  if (body.bookFile) {
    filePaths = [body.bookFile.relativePath];
    sizeBytes = body.bookFile.size || null;
  }
}

return [{ json: { source_app: app, event_type: eventType, name, file_paths: filePaths, size_bytes: sizeBytes } }];
